/**
 * Bubble Sort Algorithm Implementation
 * 
 * Bubble sort is a simple comparison-based sorting algorithm that repeatedly
 * steps through the list, compares adjacent elements, and swaps them if they
 * are in the wrong order. The process is repeated until the array is sorted.
 * 
 * Time Complexity:
 * - Best Case: O(n) - when array is already sorted
 * - Average Case: O(n²)
 * - Worst Case: O(n²) - when array is sorted in reverse order
 * 
 * Space Complexity: O(1) - sorting is done in-place
 * 
 * @param {number[]} arr - Array of integers to be sorted
 * @returns {number[]} - Sorted array in ascending order
 * @throws {Error} - If input validation fails
 */
function bubbleSort(arr) {
    // Input validation
    if (!Array.isArray(arr)) {
        throw new Error('Input must be an array');
    }

    if (arr.length > 100) {
        throw new Error('Array length must not exceed 100 elements');
    }

    // Validate each element in the array
    for (let i = 0; i < arr.length; i++) {
        if (typeof arr[i] !== 'number' || !Number.isInteger(arr[i])) {
            throw new Error(`Element at index ${i} is not an integer: ${arr[i]}`);
        }

        if (arr[i] < -10000 || arr[i] > 10000) {
            throw new Error(`Element at index ${i} is out of range [-10000, 10000]: ${arr[i]}`);
        }
    }

    // Handle edge cases
    if (arr.length <= 1) {
        return [...arr]; // Return a copy of the array
    }

    // Create a copy of the array to avoid modifying the original
    const sortedArray = [...arr];
    const n = sortedArray.length;

    // Bubble sort algorithm
    // Outer loop: controls the number of passes
    for (let i = 0; i < n - 1; i++) {
        let swapped = false; // Optimization: track if any swaps occurred

        // Inner loop: performs comparisons and swaps
        // After each pass, the largest element "bubbles up" to its correct position
        // So we can reduce the range by (i + 1) in each subsequent pass
        for (let j = 0; j < n - i - 1; j++) {
            // Compare adjacent elements
            if (sortedArray[j] > sortedArray[j + 1]) {
                // Swap elements if they are in wrong order
                const temp = sortedArray[j];
                sortedArray[j] = sortedArray[j + 1];
                sortedArray[j + 1] = temp;
                swapped = true;
            }
        }

        // Optimization: if no swaps occurred in a pass, array is already sorted
        if (!swapped) {
            break;
        }
    }

    return sortedArray;
}

/**
 * Alternative implementation with detailed step tracking (for educational purposes)
 * 
 * @param {number[]} arr - Array of integers to be sorted
 * @returns {Object} - Object containing sorted array and sorting statistics
 */
function bubbleSortWithStats(arr) {
    try {
        // Input validation (same as above)
        if (!Array.isArray(arr)) {
            throw new Error('Input must be an array');
        }

        if (arr.length > 100) {
            throw new Error('Array length must not exceed 100 elements');
        }

        for (let i = 0; i < arr.length; i++) {
            if (typeof arr[i] !== 'number' || !Number.isInteger(arr[i])) {
                throw new Error(`Element at index ${i} is not an integer: ${arr[i]}`);
            }

            if (arr[i] < -10000 || arr[i] > 10000) {
                throw new Error(`Element at index ${i} is out of range [-10000, 10000]: ${arr[i]}`);
            }
        }

        if (arr.length <= 1) {
            return {
                sortedArray: [...arr],
                comparisons: 0,
                swaps: 0,
                passes: 0
            };
        }

        const sortedArray = [...arr];
        const n = sortedArray.length;
        let comparisons = 0;
        let swaps = 0;
        let passes = 0;

        for (let i = 0; i < n - 1; i++) {
            passes++;
            let swapped = false;

            for (let j = 0; j < n - i - 1; j++) {
                comparisons++;

                if (sortedArray[j] > sortedArray[j + 1]) {
                    // Swap elements
                    const temp = sortedArray[j];
                    sortedArray[j] = sortedArray[j + 1];
                    sortedArray[j + 1] = temp;
                    swaps++;
                    swapped = true;
                }
            }

            if (!swapped) {
                break;
            }
        }

        return {
            sortedArray: sortedArray,
            comparisons: comparisons,
            swaps: swaps,
            passes: passes
        };

    } catch (error) {
        throw new Error(`Sorting failed: ${error.message}`);
    }
}

